 "content": """"Proration when a subscription changes or ends mid-period."""
from datetime import datetime, timedelta
from decimal import ROUND_HALF_DOWN, ROUND_HALF_EVEN, Decimal

_MICROSECOND = timedelta(microseconds=1)


def prorate_amount(price_cents: int, period_start: datetime, period_end: datetime, at: datetime) -> int:
    """The part of `price_cents` that covers the unused time from `at` to `period_end`, in cents."""
    for name, value in (("period_start", period_start), ("period_end", period_end), ("at", at)):
        if value.tzinfo is None or value.utcoffset() is None:
            raise ValueError(f"{name} must be a timezone-aware datetime")
    if period_end <= period_start:
        raise ValueError("period_end must be after period_start")

    at = min(max(at, period_start), period_end)
    # Exact integer microseconds keep the fraction at full precision; only the final amount is
    # rounded, and an exact half cent stays with Acme (BOPS-41).
    unused = Decimal((period_end - at) // _MICROSECOND)
    total = Decimal((period_end - period_start) // _MICROSECOND)
    return int((Decimal(price_cents) * unused / total).quantize(Decimal("1"), rounding=ROUND_HALF_DOWN))


def prorated_tax(prorated_cents, rate):
    """Tax on a prorated amount, in cents."""
    return int((Decimal(prorated_cents) * Decimal(str(rate))).quantize(Decimal("1"), rounding=ROUND_HALF_EVEN))
